import{_ as a,O as s,o as i,c as n,a as o,i as r,f as c}from"./chunks/framework.fmIt2z2h.js";const _=JSON.parse('{"title":"D.26　网络、媒体、语言、叙事与认同","description":"","frontmatter":{"title":"D.26　网络、媒体、语言、叙事与认同","xkChars":705,"xkLessons":{"D.26":{"title":"D.26　网络、媒体、语言、叙事与认同","lead":"连接、曝光、理解、信念与行动不是同一事件；事实来源独立性和社会支持人数也须分别核。","explanation":["原文定位：第4935—4950行，原站定位/theory/appendix-d/d-26#section-d-26。本题切片及完整用户原稿均在source目录，可逐字回查。","短引文：“原始事实来源重复不取消多位支持者可能产生的社会协调”。网络可带来机会，语言让经验可理解，叙事可帮助哀悼责任，身份可支持合作。分析保留正面作用，再分连接、实际帮助、曝光、阅读、信念、表达与行动，不以风险分析否定全部关系价值。[T-main]","弱联系、桥位、结构洞、中心性和真实可动员资源各有含义。某节点在图上居中不保证愿意帮、有权限帮或能及时帮；拓扑桥能传一条消息，也未必满足行动阈值、资源或安全条件。[T-main]","原文两组三人互连、一条跨组边的构造说明单提示和两邻居强化不同。需要两个不同已行动邻居时，桥端只收到一个支持可能停住；消息到达不等行动。独立重复尝试的1−(1−p)^n计算至少一次成功，不自动变成社会强化模型。[T-main]","多个节点可以共同提供支持，却转载同一事实来源。社会协调上多人到场可能重要；事实验证上则不能把同一出处的复制当多个独立证据。这两个维度都保留，不能因为来源重复便否认支持作用。[T-main]","沉默可能出于风险、隐私、未接触或无兴趣，不能自动归为赞成反对。未核实、证伪、蓄意欺骗状态不同，不能把未知直接定罪。强烈群体情绪不必非理性，真实危害也不授权对一个身份群体集体归责。[T-main]","清楚边界不必封闭，认同融合或高代价行为不自动证明自由同意。需要看实际拒绝和退出条件，不能把牺牲程度当意愿真假的万能测验，也不能仅因强认同就否认当事真实意义。[T-main]","翻译分词句、整段消息、受众任务及代表权限。语言熟练不保证听者理解、制度准入或内容可靠，翻译者也不因此代表原说话者作新承诺。后来知道的事实不能回填成当日讲述者已知的内容。[T-main]","叙事细读可解释经验意义，但不能替代技术因果。技术原因明确也不取消记忆文学的任务；它们回答不同问题。对同一事件，可以分别做机制解释与经验表达，避免互相宣布无用。[T-main]","平台处理要保留具体版本：改信息流、排序权重、匹配或作者反馈是不同干预。固定推荐规则也可经人响应形成反馈，无需每次都重训。画像变化、私人偏好、现实机会、长期伤害各需自己的证据，不能从内部模型变化直接推出人的本质偏好改变。[T-main]","历史研究参照：Guess等2023论文作者机构摘要报告2020美国选举期间，对同意用户改为逆时间序信息流，使用和曝光发生变化，三个月内考察的政治态度未显著变化。这支持分结果层和时窗，不能读成算法从无态度影响或长远效应为零。[P-GUESS]","本人只核作者机构摘要，原Science全文403，未据此补写随机化细节、效应量或统计功效。本题新增检验点是干预身份和结果变量的匹配，不把某一处理结果推广为所有平台机制。正文连接§5.5.3、5.10、§9.7、第十至十一部分和§15.3.4、15.3.6，追语义、关系、传递及实际反馈。[T-main][P-GUESS]","十二入口逐一定位：26.01弱连接结构洞问资源能否动员；26.02扩散阈值问到达和强化；26.03社会认同问边界归类；26.04议程框架问何者被看见；26.05沉默谣言问未知、错误和意图；26.06叙事记忆隐喻问意义及当时知识；26.07推荐舆情问具体处理反馈；26.08翻译迁移问任务与权限；26.09语言学习制度问准入；26.10不确定性认同与差异性问归属需求；26.11情绪恐惧道德恐慌问证据与归责；26.12认同融合高代价经历问意义和自愿。列名作者是研究导航，不宣称完整核读其全部理论。[T-main]"],"argumentSteps":["明确图结构、规则、种子状态与时序。","分曝光理解信念表达行动各观测量。","分来源独立性与社会支持人数。","核实际平台处理及反馈路径，不用总标签替代。","把结论限制在所读证据、对象与时窗，保留意义任务。"],"distinctions":[{"leftTitle":"消息到达","leftText":"收到内容。","rightTitle":"行动发生","rightText":"还可能需要不同邻居支持及资源。"},{"leftTitle":"独立重复尝试","leftText":"至少一次成功概率。","rightTitle":"社会强化","rightText":"多个社会位置支持的机制，不自动等价。"},{"leftTitle":"来源重复","leftText":"事实证据可能同源。","rightTitle":"支持多人","rightText":"仍可能产生真实协调。"},{"leftTitle":"非显著","leftText":"该设计统计结果。","rightTitle":"永久零效应","rightText":"不能由有限窗口非显著推出。"}],"boundaries":["原文教学反例：一条桥边可传消息，却不足满足两邻居支持阈值。","原文边界：沉默不能自动推成赞成或反对。","原文反例：固定规则可经人的响应反馈，不必重训。"],"questions":["同源多人支持完全没用吗？","三次成功公式何时可用？","算法没重训能有反馈吗？","三月不显著说明永远没影响吗？"],"diagramPath":"/reading-assets/S-D-26/figures/d26-bridge.png","caseLinks":[{"title":"2020选举信息流处理研究的2023作者摘要","href":"https://www.networkscienceinstitute.org/publications/how-do-social-media-feed-algorithms-affect-attitudes-and-behavior-in-an-election-campaign"}],"caseNotes":[{"title":"2020选举信息流处理研究的2023作者摘要","text":"同意参与用户改逆时间序信息流，使用和曝光变化；三个月窗口所测政治态度未显著变化。","sourceLabel":"Guess et al. 2023: How do social media feed algorithms affect attitudes and behavior in an election campaign? 作者机构摘要","sourceUrl":"https://www.networkscienceinstitute.org/publications/how-do-social-media-feed-algorithms-affect-attitudes-and-behavior-in-an-election-campaign","sourceLocator":"NetSI原作者机构页面Abstract（正文13—15行）","boundary":"只读作者机构摘要，Science全文403；不推长期零效应，不扩为所有推荐算法的结果。","href":"https://www.networkscienceinstitute.org/publications/how-do-social-media-feed-algorithms-affect-attitudes-and-behavior-in-an-election-campaign"}],"sourceRefs":[{"section":"D.26","start_line":4935,"end_line":4950,"startLine":4935,"endLine":4950}],"outputId":"section-d-26","sourceHash":"df579dbdbb68442b1781b066606c267761f0a1673fbd034ce93eeeb41641439f","teachingExamples":[{"title":"教学构造：桥与阈值","text":"图为三角ABC和三角DEF，唯一桥C—D。初始ABC均已行动，DEF未行动。同步单调更新：阈值1时第1轮D行动、第2轮E和F行动；阈值2时D仅有C一个已行动邻居，E/F都无，之后永久停在ABC。","assumptions":"人工无向图、同步确定阈值、无自发种子及外部输入。","boundary":"只说明指定构造，不推出现实所有桥都无用或所有复杂传播必停。"},{"title":"教学构造：独立尝试概率","text":"人工每次成功p=1/2且三次独立，至少一次成功为1−(1/2)^3=7/8。若三次完全同源且同成同败，至少一次成功仍1/2。不能未核独立就用7/8，更不能直接称三人社会强化。","assumptions":"明确独立或完全相关两个不同模型。","boundary":"不是平台实测成功率。"}],"counterexamples":[{"identity":"constructed_boundary","text":"原文教学反例：一条桥边可传消息，却不足满足两邻居支持阈值。","effect":"限制本节的无条件延伸；不否定具有独立依据的有限判断。","sourceIds":["T-main"]},{"identity":"source_counterexample","text":"原文边界：沉默不能自动推成赞成或反对。","effect":"限制本节的无条件延伸；不否定具有独立依据的有限判断。","sourceIds":["T-main"]},{"identity":"source_counterexample","text":"原文反例：固定规则可经人的响应反馈，不必重训。","effect":"限制本节的无条件延伸；不否定具有独立依据的有限判断。","sourceIds":["T-main"]}],"questionAnswers":[{"question":"同源多人支持完全没用吗？","answer":"不，事实独立性不足不取消社会协调。","basis":"双维度。"},{"question":"三次成功公式何时可用？","answer":"需相同成功率和独立等给定条件。","basis":"概率假设。"},{"question":"算法没重训能有反馈吗？","answer":"能，人的响应可改变后续输入。","basis":"反馈路径。"},{"question":"三月不显著说明永远没影响吗？","answer":"不能，保留时窗和测量限制。","basis":"实证范围。"}],"figures":[{"path":"/reading-assets/S-D-26/figures/d26-bridge.png","alt":"两三角一桥，阈值1扩散，阈值2停。","caption":"教学构造。"},{"path":"/reading-assets/S-D-26/figures/d26-outcomes.png","alt":"信息流改变可影响使用曝光，态度和长期结果另核。","caption":"作者机构摘要范围。"},{"path":"/reading-assets/S-D-26/figures/d26-source.png","alt":"独立证据与多个支持者是两维，不能互相取消。","caption":"据D.26。"}],"diagramBrief":"三图呈现桥阈值构造、结果分层与来源支持区分。","applicability":{"realCase":"applicable","diagram":"applicable","reason":"本单元涉及方法判断，真实来源仅支持所列事实；图与教学构造分别保留其身份。"},"openQuestions":["未读原论文完整方法、效应估计或统计功效。","人工网络无外部种子，现实阈值与异质性未估计。"],"taskId":"S-D-26","sources":[{"id":"T-main","title":"Xikari著《Xikari-条件结构与转化论》","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68；文本自述2026年10月","locator":"§D.26，第4935—4950行","claim_support":["网络阈值、语义认同、来源支持、平台版本反馈及十二入口。"],"limits":["支持当前稿的文本含义与明确限定的推理；不自行证明经验普遍性、实施效果或读者学习成效。"],"access_status":"read"},{"id":"P-GUESS","title":"Guess et al. 2023: How do social media feed algorithms affect attitudes and behavior in an election campaign? 作者机构摘要","url":"https://www.networkscienceinstitute.org/publications/how-do-social-media-feed-algorithms-affect-attitudes-and-behavior-in-an-election-campaign","source_type":"primary","version_or_date":"2023论文；2020研究窗口","locator":"NetSI原作者机构页面Abstract（正文13—15行）","claim_support":["2020美国选举期间，对同意参与用户改为逆时间序信息流，使用及曝光改变；三个月窗口内报告所考察政治态度没有显著变化。"],"limits":["本人读机构所刊原作者摘要；Science全文取回403，未读完整方法或效应量/功效，不将非显著解释为永久零效应。"],"access_status":"partially_read"}],"lecturePath":"/reading-assets/S-D-26/lecture.md","sourcesPath":"/reading-assets/S-D-26/sources.json","sourceSlicePath":"/reading-assets/S-D-26/source/S-D-26.md","supplementaryFiles":[],"diagramsPath":"/reading-assets/S-D-26/diagrams.md"}}},"headers":[],"relativePath":"theory/appendix-d/d-26.md","filePath":"theory/appendix-d/d-26.md"}'),d={name:"theory/appendix-d/d-26.md"};function l(p,e,u,m,f,h){const t=s("SectionLesson");return i(),n("div",null,[e[0]||(e[0]=o('<div class="theory-source"><h1 id="section-d-26" tabindex="-1"><span class="xk-num"><span class="xk-num__n">D.26</span><span class="xk-num__gap">　</span></span>网络、媒体、语言、叙事与认同 <a class="header-anchor" href="#section-d-26" aria-label="Permalink to &quot;D.26　网络、媒体、语言、叙事与认同 {#section-d-26}&quot;">​</a></h1><p>正文连接：§5.5.3、5.10；§9.7；§10—11；§15.3.4、15.3.6。研究入口：26.01—26.12。</p><p>网络可以带来机会，语言可以使经验被理解，叙事可以帮助哀悼和责任讨论，身份可以支持合作。分析应保留这些正面作用，同时区分连接、实际帮助、曝光、阅读、信念、公开表达和行动。弱联系、桥位、结构洞、中心性与真实可动员资源不是同义词。</p><p>教学例：两组三人各自互连，组间只有一条边。若收到一个已行动邻居提示就采取行动，传播可能跨过去；若需要两个不同邻居共同支持，消息到达也未必足够。重复独立尝试的累计成功率1−(1−p)^n，不等于社会强化。多个社会节点可以提供支持，却仍共用同一事实来源。</p><p>沉默可能来自风险、隐私、未接触或无兴趣，不能自动推成赞成或反对。未核实、已证明错误和蓄意欺骗是不同状态；强烈群体情绪不必不理性，真实危害也不能让一个身份群体承担全部责任。清楚边界不等封闭，认同融合或高代价行为不自动证明自由同意。</p><p>翻译要分词句、整段消息、受众任务和代表权限；语言能力、听者理解、制度准入与内容质量各有通道。叙事细读可以解释经验和意义，却不替代技术因果；反过来，技术原因明确也不使记忆与文学任务多余。后来取得的事实不能回填为当日讲述者已经知道的内容。</p><p>平台处理需保留实际版本：改变信息流、某项排序权重、内容匹配或作者反馈，不能共用一个处理标签。固定推荐规则也可以经人的响应形成反馈，模型重训不是所有反馈的必要条件。系统画像变化、私人偏好、实际机会和长期伤害分别评价；原始事实来源重复不取消多位支持者可能产生的社会协调。</p><p>专题定位：26.01 弱连接、结构洞与网络资源：Granovetter、Burt；26.02 扩散、阈值与复杂传播：Granovetter、Watts、Centola；26.03 社会认同、自我分类与群体边界：Tajfel、John Turner；26.04 议程设置、框架与媒介选择；26.05 沉默、螺旋、谣言与错误信息；26.06 叙事、记忆、隐喻与公共解释；26.07 平台注意力、推荐与舆情；26.08 跨语言翻译与概念迁移；26.09 语言学习、语言制度与表达不平等；26.10 不确定性—认同与最优差异性；26.11 群体情绪、恐惧管理与道德恐慌；26.12 认同融合与高代价共同经历。</p></div>',1)),r(t,{section:"D.26"}),e[1]||(e[1]=c("div",{class:"theory-source"},null,-1))])}const b=a(d,[["render",l]]);export{_ as __pageData,b as default};
